-- ============================================================
-- 京懐石・一汁三菜（テーマID: 22, category_id: 3）問題投入SQL
-- 全20問（難易度1〜3）
-- 選択肢対応: (ア)=0, (イ)=1, (ウ)=2, (エ)=3
-- ============================================================

INSERT INTO questions (category_id, theme_id, question_text, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty_level, is_premium) VALUES

(3, 22, '懐石料理の起源として正しいのはどれか。', '宮廷の饗宴料理', '茶の湯の場で提供された簡素な食事', '武家社会の格式料理', '精進料理が発展したもの', 1, '懐石料理は茶道（茶の湯）において、濃茶の前に客をもてなすために提供された軽い食事が起源です。「懐石」は禅僧が空腹をしのぐため懐に温めた石を抱いたことに由来するとも言われています。', 1, false),
(3, 22, '「一汁三菜（いちじゅうさんさい）」の構成として正しいのはどれか。', '汁一品・菜三品（飯別）', '汁一品・おかず三品・デザート', '汁物三種・菜一品', 'スープ・サラダ・メイン・デザート', 0, '一汁三菜とは「汁もの一品・おかず（菜）三品（向付・煮物・焼き物）」を基本構成とした和食の献立様式です。ご飯・香の物（漬物）を加えた構成が基本形で、日本の伝統的な食事様式の原型とされています。', 1, false),
(3, 22, '「懐石（かいせき）」と「会席（かいせき）」の違いとして正しいのはどれか。', 'まったく同じ料理', '懐石は茶事の食事・会席は宴会の料理', '懐石は精進料理・会席は肉料理', '懐石は高級・会席は大衆向け', 1, '「懐石」は茶道の茶事で提供される簡素な料理（茶懐石）を指し、「会席」は宴会・酒席で供される豪華な料理です。どちらも「かいせき」と読みますが、起源・目的・内容が異なります。', 1, false),
(3, 22, '京懐石で最初に出される料理で、向付（むこうづけ）の典型的な内容はどれか。', '熱いお椀料理', '刺身・酢の物など', '焼き物', '蒸し物', 1, '向付（むこうづけ）は懐石の最初に出される料理で、刺身・膾（なます）・酢の物などが盛り付けられます。器の「向こう側（遠い方）」に置かれることから「向付」と呼ばれます。', 1, false),
(3, 22, '茶懐石で「八寸（はっすん）」とはどのような料理か。', '8寸（約24cm）の皿に盛った料理', '海の幸・山の幸を盛り合わせた二種の酒肴', '8種類のお菓子の盛り合わせ', '8人分の取り分け料理', 1, '八寸（はっすん）は約8寸（約24cm）の四角い杉の盆に、海の幸・山の幸を一品ずつ盛り合わせた酒肴です。茶懐石で酒を飲む際に出され、亭主みずから運ぶしきたりがあります。', 2, false),
(3, 22, '京懐石・精進料理などで使われる「だし（出汁）」として京都で最も基本とされるものはどれか。', '鰹節だし', '昆布だし', '合わせだし（鰹+昆布）', '煮干しだし', 1, '京料理では昆布だし（昆布から取っただし）が最も基本とされています。魚の利用が限られていた内陸の京都では、昆布の上品なうまみを生かした淡い味付けが発達しました。合わせだしも広く使われます。', 2, false),
(3, 22, '「精進料理（しょうじんりょうり）」と「懐石料理」の共通点はどれか。', '肉類を一切使わない', '旬の食材を大切にする', '宗教儀式のための料理', '厳格に一汁三菜の形式をとる', 1, '精進料理と懐石料理の共通点として「旬の食材を大切にする」点があります。精進料理は仏教の戒律に基づき殺生を避けますが、現代の懐石料理は魚介類も使います。ただし季節感・素材の味を生かす点は共通しています。', 2, false),
(3, 22, '「向付（むこうづけ）」の次に出される懐石の椀物として代表的なのはどれか。', '汁物（みそ汁）', '強肴（しいざかな）', 'お造り（刺身）', '焼き物（焼き魚）', 0, '懐石の流れは「飯・汁・向付」→「煮物椀（煮物の入った汁椀）」→「焼き物」の順が基本です。汁物は最初の「一汁」に含まれ、みそ汁か澄まし汁が出されます。', 2, false),
(3, 22, '「京懐石」で重要視される「盛り付け（もりつけ）」の美意識として最も適切なのはどれか。', '皿に料理を余白なく盛り付ける', '器の余白を生かし少量を品よく盛る', '西洋料理のようにソースで飾る', '食べやすさだけを優先する', 1, '京懐石の盛り付けは「余白の美」を大切にし、器の余白を生かして少量の料理を品よく盛るのが原則です。料理と器の一体感・季節感を演出することが重視され、見た目の美しさも料理の一部とされています。', 1, false),
(3, 22, '京料理の味付けの特徴として最も正しいのはどれか。', '濃い味・辛い味付け', '薄口醤油・昆布だしを活かした淡い上品な味付け', '甘みが非常に強い', '辛さと甘さのコントラストが特徴', 1, '京料理は薄口醤油・昆布だしを多用した淡い色と上品な味付けが特徴です。食材の色・形・味を生かす調理が原則で、素材の味を消さないシンプルな味付けが伝統的な美意識とされています。', 1, false),
(3, 22, '茶懐石の「強肴（しいざかな）」の役割はどれか。', '食事の最初に出る前菜', '酒を飲むために追加で出される料理', 'デザートとして最後に出る菓子', '主菜として単独で出る魚料理', 1, '強肴（しいざかな）は茶懐石において酒を勧める際に追加で出される料理（酒肴）です。焼き物・煮物の後に出され、客が酒を楽しむためのつまみとして機能します。', 3, false),
(3, 22, '「精進落とし（しょうじんおとし）」とは京都の食文化ではどのような意味か。', '精進料理を始めること', '忌中明けや彼岸明けに魚・肉を食べること', '仏事の料理を終了すること', '断食を終了すること', 1, '「精進落とし（しょうじんおとし）」は忌中（喪中）や彼岸・斎日の精進期間が終わり、魚・肉などを解禁することです。葬儀後の会食（精進落としの会食）として広く行われています。', 2, false),
(3, 22, '京都の料理文化で「おばんざい」に多く使われる食材として正しいのはどれか。', '高級食材（フォアグラ・トリュフなど）', '旬の野菜・豆腐・乾物などの身近な食材', '輸入した海外の食材', '肉類中心の食材', 1, '「おばんざい」は京都の家庭料理・惣菜の総称で、旬の野菜・豆腐・高野豆腐・干し物・漬物など身近な食材を使ったシンプルな料理が中心です。素材の味を生かした淡い味付けが特徴です。', 1, false),
(3, 22, '「湯豆腐（ゆどうふ）」が京都の名物として特に知られる地域はどこか。', '伏見', '南禅寺周辺', '嵐山', '西陣', 1, '南禅寺周辺（東山区）は湯豆腐の名所として有名で、多くの湯豆腐専門店が軒を連ねています。京都の豆腐は水がよい（鴨川・地下水）ことで有名で、なめらかな京豆腐が湯豆腐に最適とされています。', 1, false),
(3, 22, '「だし巻き卵（だしまきたまご）」が京都の食文化で大切にされる理由として最も適切なのはどれか。', '卵を大量消費するため', '出汁のうまみを存分に楽しめる料理だから', '外国人向けに開発された料理だから', '保存食として発達したから', 1, 'だし巻き卵は溶き卵に昆布・鰹だしをたっぷり加えて巻いた卵料理で、だしの風味をストレートに楽しめる料理です。京料理では「だしの使い方がわかる」料理として職人技の重要な一品とされています。', 2, false),
(3, 22, '「西京漬け（にしきょうづけ）」の材料として正しいのはどれか。', '醤油と酒', '西京みそ（白みそ）', 'ポン酢と塩', 'ワサビ醤油', 1, '西京漬けは西京みそ（甘みのある白みそ）に魚や肉を漬け込んだ料理です。銀ダラ・サワラ・鮭などの西京漬けが有名で、白みその甘みと素材のうまみが合わさった上品な味わいが特徴です。', 1, false),
(3, 22, '「鰻（うなぎ）」と並ぶ夏の京料理として、祇園祭の時期に食べる魚はどれか。', '鮎（あゆ）', '鱧（はも）', '鯉（こい）', '川魚全般', 1, '鱧（はも）は夏の京料理を代表する魚で、特に祇園祭の時期（7月）に食べる習慣があります。「鱧まつり」とも呼ばれる祇園祭の時期に骨切りという独特の調理法で提供され、落とし・椀物・鍋などに使われます。', 1, false),
(3, 22, '「千枚漬け（せんまいづけ）」に使われる野菜はどれか。', '賀茂なす', '聖護院大根', '万願寺とうがらし', '九条ねぎ', 1, '千枚漬けは聖護院大根（しょうごいんだいこん）を薄く切り、昆布・酢・塩などで漬けた京都を代表する漬物です。薄さと繊細な甘みが特徴で、冬の京都を代表する漬物として全国に知られています。', 1, false),
(3, 22, '「一汁三菜」が「ユネスコ無形文化遺産」に登録された「和食」の代表的な要素として認められたのはいつか。', '2003年', '2013年', '2018年', '2020年', 1, '「和食：日本人の伝統的な食文化」は2013年にユネスコ無形文化遺産に登録されました。「一汁三菜」の伝統・旬の食材の尊重・自然の美の表現・年中行事との関わりなどが評価されました。', 2, false),
(3, 22, '懐石料理で「飯（めし）」が最初に出されることの意味として正しいのはどれか。', '腹を満たしてから酒を飲むため', '茶の湯では酒の前に飯を食べることで正式な作法となっているから', '消化を助けるため', 'デザートとして飯を最後に食べる西洋と対比するため', 1, '茶懐石では飯・汁・向付が最初に揃って出されます。これは茶事のもてなしとして「食事をきちんと提供する」ことを示す正式な作法です。飯を先に食べることで、後から出る酒肴を楽しむ流れが整えられます。', 3, false);

